		// perdido por una preferencia heredada del usuario en Gutenberg.
		add_filter( 'hidden_meta_boxes', array( __CLASS__, 'keep_snippet_visible' ), 10, 2 );
		add_action( 'init', array( __CLASS__, 'taxonomies' ) ); add_action( 'created_term', array( __CLASS__, 'save_term' ), 10, 3 ); add_action( 'edited_term', array( __CLASS__, 'save_term' ), 10, 3 );
		remove_action( 'wp_head', 'rel_canonical' ); add_filter( 'pre_get_document_title', array( __CLASS__, 'title' ), 20 ); add_action( 'wp_head', array( __CLASS__, 'head' ), 1 ); add_action( 'wp_head', array( __CLASS__, 'content_location_schema' ), 2 ); add_filter( 'wp_robots', array( __CLASS__, 'robots' ) );
		add_filter( 'wp_sitemaps_enabled', array( __CLASS__, 'sitemap_enabled' ) ); add_filter( 'wp_sitemaps_post_types', array( __CLASS__, 'sitemap_posts' ) ); add_filter( 'wp_sitemaps_taxonomies', array( __CLASS__, 'sitemap_terms' ) ); add_filter( 'wp_sitemaps_posts_query_args', array( __CLASS__, 'sitemap_query' ), 10, 2 );
		add_action( 'template_redirect', array( __CLASS__, 'attachment_redirect' ) ); add_shortcode( 'digitalisimo_breadcrumbs', array( __CLASS__, 'breadcrumb_shortcode' ) );
		if ( is_multisite() ) add_action( 'network_admin_edit_digitalisimo_save_network_seo', array( __CLASS__, 'save_network' ) );
	}
	private static function o( $key, $default = '' ) { return Digitalisimo_Integrations_Settings::get( $key, $default ); }
	private static function m( $id, $key, $default = '' ) { return Digitalisimo_Integrations_SEO_Resolver::post( $id, $key, $default ); }
	private static function list_value( $key ) { return array_filter( array_map( 'sanitize_key', array_map( 'trim', explode( ',', (string) self::o( $key ) ) ) ) ); }
	private static function editable_types() { return get_post_types( array( 'public' => true, 'show_ui' => true ), 'names' ); }
	public static function menu() {
		// Un único acceso SEO. Los ajustes viven en pestañas para no dispersar la navegación.
		add_submenu_page( 'digitalisimo', 'SEO', 'SEO', 'manage_options', 'digitalisimo-seo', array( __CLASS__, 'page' ) );
		$advanced = array( 'digitalisimo-seo-general', 'digitalisimo-seo-titles', 'digitalisimo-seo-appearance', 'digitalisimo-seo-schema', 'digitalisimo-seo-local', 'digitalisimo-seo-social', 'digitalisimo-seo-sitemap', 'digitalisimo-seo-indexing', 'digitalisimo-seo-breadcrumbs', 'digitalisimo-seo-diagnostic', 'digitalisimo-seo-tools' );
		foreach ( $advanced as $slug ) add_submenu_page( null, 'SEO', 'SEO', 'manage_options', $slug, array( __CLASS__, 'page' ) );
		$editorial = array( 'digitalisimo-content' => array( 'Contenido', 'content_page' ), 'digitalisimo-keywords' => array( 'Keywords', 'keywords_page' ), 'digitalisimo-clusters' => array( 'Clusters', 'clusters_page' ), 'digitalisimo-intents' => array( 'Intención SEO', 'intents_page' ) );
		foreach ( $editorial as $slug => $page ) add_submenu_page( null, $page[0], $page[0], 'manage_options', $slug, array( 'Digitalisimo_Integrations_SEO', $page[1] ) );
	}
	/** Una navegación persistente para los ajustes y la estrategia editorial de SEO. */
	public static function navigation_tabs( $active = 'dashboard' ) {
		$tabs = array( 'dashboard' => 'Resumen', 'general' => 'Identidad', 'titles' => 'Títulos', 'schema' => 'Schema', 'social' => 'Social', 'local' => 'Local', 'indexing' => 'Indexación', 'sitemap' => 'Sitemap', 'breadcrumbs' => 'Breadcrumbs', 'tools' => 'Avanzado', 'content' => 'Contenido', 'diagnostic' => 'SEO Front' );
		echo '<h2 class="nav-tab-wrapper digitalisimo-tabs">'; foreach ( $tabs as $tab => $label ) { $target = 'dashboard' === $tab ? 'digitalisimo-seo' : ( 'content' === $tab ? 'digitalisimo-content' : 'digitalisimo-seo-' . $tab ); echo '<a class="nav-tab ' . ( $active === $tab ? 'nav-tab-active' : '' ) . '" href="' . esc_url( admin_url( 'admin.php?page=' . $target ) ) . '">' . esc_html( $label ) . '</a>'; } echo '</h2>';
	}
	public static function network_menu() { add_menu_page( 'Digitalisimo', 'Digitalisimo', 'manage_network_options', 'digitalisimo-network-seo', array( __CLASS__, 'network_page' ), 'dashicons-chart-line', 56 ); add_submenu_page( 'digitalisimo-network-seo', 'SEO', 'SEO', 'manage_network_options', 'digitalisimo-network-seo', array( __CLASS__, 'network_page' ) ); }
	public static function network_page() {
		if ( ! is_multisite() || ! current_user_can( 'manage_network_options' ) || ! is_super_admin() ) return; $tab = sanitize_key( $_GET['tab'] ?? 'general' ); $tabs = array( 'general' => 'General', 'location' => 'Ubicación', 'schema' => 'Schema', 'social' => 'Social', 'indexing' => 'Indexación', 'sitemap' => 'Sitemap', 'keywords' => 'Keywords', 'defaults' => 'Defaults' ); if ( ! isset( $tabs[ $tab ] ) ) $tab = 'general'; echo '<div class="wrap"><h1>Digitalisimo · Configuración de red</h1><p>Estos valores se heredan dinámicamente en los sitios que no los hayan personalizado.</p><h2 class="nav-tab-wrapper digitalisimo-tabs">'; foreach ( $tabs as $slug => $name ) echo '<a class="nav-tab ' . ( $tab === $slug ? 'nav-tab-active' : '' ) . '" data-tab="' . esc_attr( $slug ) . '" href="' . esc_url( network_admin_url( 'admin.php?page=digitalisimo-network-seo&tab=' . $slug ) ) . '">' . esc_html( $name ) . '</a>'; echo '</h2><form method="post" action="' . esc_url( network_admin_url( 'edit.php?action=digitalisimo_save_network_seo' ) ) . '">'; wp_nonce_field( 'digitalisimo_network_seo' ); echo '<input type="hidden" class="digitalisimo-active-tab" name="digitalisimo_active_tab" value="' . esc_attr( $tab ) . '">'; // Todas las pestañas en el mismo formulario: cambiar de pestaña no recarga ni pierde lo escrito.
		foreach ( $tabs as $slug => $name ) { echo '<div class="digitalisimo-panel" data-tab="' . esc_attr( $slug ) . '"' . ( $slug === $tab ? '' : ' hidden' ) . '><table class="form-table" role="presentation">'; self::network_fields( $slug ); if ( 'defaults' === $slug ) self::network_cluster_field(); echo '</table></div>'; } submit_button( 'Guardar configuración de red' ); echo '</form></div>';
	}
