	private static function nf( $key, $label, $type = 'text', $help = '' ) { $all = (array) get_site_option( Digitalisimo_Integrations_Settings::OPTION, array() ); $defaults = Digitalisimo_Integrations_Settings::defaults(); $value = $all[ $key ] ?? ( $defaults[ $key ] ?? '' ); $secret = in_array( $key, self::secret_keys(), true ); $name = 'digitalisimo_network[' . $key . ']'; echo '<tr><th scope="row"><label for="network_' . esc_attr( $key ) . '">' . esc_html( $label ) . '</label></th><td>'; if ( 'media' === $type ) { Digitalisimo_Media_Field::render( 'network_' . $key, $name, $value ); } elseif ( 'checkbox' === $type ) echo '<input type="hidden" name="' . esc_attr( $name ) . '" value="0"><label><input type="checkbox" id="network_' . esc_attr( $key ) . '" name="' . esc_attr( $name ) . '" value="1" ' . checked( $value, 1, false ) . '> Activar</label>'; elseif ( $secret && 'textarea' === $type ) echo '<textarea class="large-text" rows="4" id="network_' . esc_attr( $key ) . '" name="' . esc_attr( $name ) . '" placeholder="Uno por línea"></textarea>'; elseif ( 'textarea' === $type ) echo '<textarea class="large-text" rows="4" id="network_' . esc_attr( $key ) . '" name="' . esc_attr( $name ) . '">' . esc_textarea( $value ) . '</textarea>'; elseif ( $secret ) echo '<input class="regular-text" type="password" autocomplete="new-password" id="network_' . esc_attr( $key ) . '" name="' . esc_attr( $name ) . '" value="" placeholder="' . esc_attr( ! empty( $value ) ? Digitalisimo_Integrations_Settings::MASK : 'API Key' ) . '">'; else echo '<input class="regular-text" type="' . esc_attr( $type ) . '" id="network_' . esc_attr( $key ) . '" name="' . esc_attr( $name ) . '" value="' . esc_attr( $value ) . '">'; if ( $secret ) echo ' <span class="digitalisimo-secret ' . ( ! empty( $value ) ? 'is-set' : 'is-empty' ) . '">' . esc_html( ! empty( $value ) ? 'Guardada · escribe una nueva sólo si quieres reemplazarla' : 'Sin configurar' ) . '</span>'; if ( $help ) echo '<p class="description">' . esc_html( $help ) . '</p>'; echo '</td></tr>'; }
	private static function network_cluster_field() { $key = 'default_cluster_pillar'; $all = (array) get_site_option( Digitalisimo_Integrations_Settings::OPTION, array() ); $value = (string) ( $all[ $key ] ?? '' ); echo '<tr><th scope="row"><label for="network_default_cluster_pillar">Contenido pilar predeterminado</label></th><td>'; Digitalisimo_Integrations_Editorial::cluster_slug_select( 'digitalisimo_network[' . $key . ']', $value, 'network_default_cluster_pillar' ); echo '<p class="description">Se guarda por slug y se vincula al contenido publicado equivalente de cada sitio que hereda la configuración de red. Se asigna sólo a contenido nuevo.</p></td></tr>'; }
	private static function network_fields( $tab ) { if ( 'general' === $tab ) { self::nf( 'seo_organization_name', 'Nombre de la organización' ); self::nf( 'seo_site_name', 'Nombre comercial / Site Name' ); self::nf( 'seo_organization_type', 'Tipo de Organization' ); self::nf( 'seo_organization_url', 'URL principal', 'url' ); self::nf( 'seo_organization_email', 'Email' ); self::nf( 'seo_logo', 'Logo principal', 'media' ); Digitalisimo_Integrations_Social_Profiles::network_fields(); self::nf( 'seo_knowledge_urls', 'Otros perfiles', 'textarea', 'Sólo para perfiles sin campo propio. Uno por línea.' ); } if ( 'general' === $tab ) { self::nf( 'seo_separator', 'Separador de títulos' ); self::nf( 'seo_default_image', 'Imagen social predeterminada', 'media' ); self::nf( 'seo_hide_login_slug', 'Ruta privada de acceso', 'text', 'Se aplica a cada sitio de la red sobre su propio dominio: el sitio A abre /ruta y el sitio B /su-sitio/ruta. Vacío conserva el acceso estándar. Un sitio sólo usa su propio valor si desmarca «Heredar de la red» en Digitalisimo → SEO → General.' ); } if ( 'location' === $tab ) { self::nf( 'seo_local_enabled', 'SEO Local', 'checkbox' ); self::nf( 'seo_local_name', 'Nombre comercial' ); echo '<tr><th scope="row">Teléfono</th><td>'; Digitalisimo_Integrations_Local_Business::network_phone_field(); echo '</td></tr>'; self::nf( 'seo_local_address', 'Dirección', 'textarea' ); self::nf( 'seo_local_city', 'Ciudad principal' ); self::nf( 'seo_local_region', 'Estado / región' ); self::nf( 'seo_local_country', 'País' ); self::nf( 'seo_local_postal', 'Código postal' ); self::nf( 'seo_local_latitude', 'Latitud' ); self::nf( 'seo_local_longitude', 'Longitud' ); echo '<tr><th scope="row">Horario</th><td>'; Digitalisimo_Integrations_Local_Business::network_schedule_field(); echo '</td></tr>'; } if ( 'schema' === $tab ) { self::nf( 'seo_schema_enabled', 'Schema activo', 'checkbox' ); self::nf( 'seo_title_post', 'Título predeterminado de entradas' ); self::nf( 'seo_title_page', 'Título predeterminado de páginas' ); } if ( 'social' === $tab ) { self::nf( 'seo_open_graph', 'Open Graph activo', 'checkbox' ); self::nf( 'seo_twitter_enabled', 'Twitter Cards activas', 'checkbox' ); self::nf( 'seo_twitter_user', 'Usuario X/Twitter' ); echo '<tr><th scope="row">Imagen social</th><td><p class="description">Se configura en la pestaña General, junto al resto de la identidad del sitio.</p></td></tr>'; } if ( 'indexing' === $tab ) { foreach ( array( 'noindex_search' => 'Noindex resultados de búsqueda', 'noindex_authors' => 'Noindex autores', 'noindex_empty_tags' => 'Noindex tags vacíos', 'noindex_date_archives' => 'Noindex archivos por fecha', 'noindex_attachments' => 'Noindex adjuntos', 'noindex_elementor' => 'Noindex Elementor', 'noindex_woo_pages' => 'Noindex páginas WooCommerce' ) as $key => $label ) self::nf( $key, $label, 'checkbox' ); self::nf( 'noindex_page_slugs', 'Slugs noindex', 'textarea' ); self::nf( 'noindex_page_ids', 'IDs noindex', 'textarea' ); } if ( 'sitemap' === $tab ) { self::nf( 'sitemap_enabled', 'Sitemap activo', 'checkbox' ); self::nf( 'sitemap_post_types', 'Tipos incluidos', 'textarea' ); self::nf( 'seo_sitemap_taxonomies', 'Taxonomías incluidas', 'textarea' ); self::nf( 'sitemap_exclude_ids', 'IDs excluidos', 'textarea' ); } if ( 'keywords' === $tab ) { self::nf( 'keyword_post_types', 'Tipos de contenido', 'textarea' ); self::nf( 'keyword_max_count', 'Máximo de keywords', 'number' ); self::nf( 'keyword_auto_from_title', 'Keyword desde título', 'checkbox' ); self::nf( 'openai_model', 'Modelo de intención SEO' ); } if ( 'integrations' === $tab ) { self::nf( 'enable_seo', 'Módulo SEO', 'checkbox' ); self::nf( 'enable_woocommerce', 'Módulo WooCommerce', 'checkbox' ); self::nf( 'enable_ipinfo', 'Módulo IPinfo', 'checkbox' ); self::nf( 'openai_api_key', 'Clave OpenAI' ); self::nf( 'openai_model', 'Modelo OpenAI' ); self::nf( 'ipinfo_tokens', 'Tokens IPinfo', 'textarea' ); self::nf( 'ipinfo_cache_minutes', 'Caché IPinfo (minutos)', 'number' ); self::nf( 'namecheap_api_user', 'Usuario API Namecheap' ); self::nf( 'namecheap_username', 'Usuario Namecheap' ); self::nf( 'namecheap_api_key', 'Clave API Namecheap' ); self::nf( 'namecheap_client_ip', 'IP autorizada Namecheap' ); self::nf( 'domain_products', 'Productos de dominio', 'textarea' ); self::nf( 'hosting_product_ids', 'Productos hosting', 'textarea' ); self::nf( 'hosting_category_ids', 'Categorías hosting', 'textarea' ); self::nf( 'require_domain_hosting', 'Exigir dominio y hosting juntos', 'checkbox' ); self::nf( 'replace_hosting', 'Sustituir hosting anterior', 'checkbox' ); self::nf( 'simplify_checkout', 'Simplificar checkout', 'checkbox' ); } if ( 'defaults' === $tab ) { self::nf( 'seo_description_post', 'Descripción predeterminada entradas', 'textarea' ); self::nf( 'seo_description_page', 'Descripción predeterminada páginas', 'textarea' ); self::nf( 'seo_title_archive', 'Título predeterminado archivos' ); self::nf( 'seo_description_archive', 'Descripción predeterminada archivos', 'textarea' ); self::nf( 'seo_breadcrumbs', 'Breadcrumbs activos', 'checkbox' ); self::nf( 'seo_redirect_attachments', 'Redirigir adjuntos', 'checkbox' ); } }
	public static function save_network() { if ( ! is_multisite() || ! current_user_can( 'manage_network_options' ) || ! is_super_admin() || ! check_admin_referer( 'digitalisimo_network_seo' ) ) wp_die( 'No autorizado.' ); $input = (array) wp_unslash( $_POST['digitalisimo_network'] ?? array() ); $current = (array) get_site_option( Digitalisimo_Integrations_Settings::OPTION, array() ); $checkboxes = array( 'enable_seo', 'enable_woocommerce', 'enable_ipinfo', 'keyword_auto_from_title', 'seo_local_enabled', 'seo_schema_enabled', 'seo_open_graph', 'seo_twitter_enabled', 'seo_breadcrumbs', 'sitemap_enabled', 'seo_redirect_attachments', 'noindex_search', 'noindex_authors', 'noindex_empty_tags', 'noindex_date_archives', 'noindex_attachments', 'noindex_elementor', 'noindex_woo_pages', 'require_domain_hosting', 'replace_hosting', 'simplify_checkout' ); foreach ( $input as $key => $value ) { if ( ! array_key_exists( $key, Digitalisimo_Integrations_Settings::defaults() ) ) continue; if ( in_array( $key, $checkboxes, true ) ) { $current[ $key ] = empty( $value ) ? 0 : 1; continue; } // Un secreto vacío conserva el valor almacenado en lugar de borrarlo.
			if ( 'default_cluster_pillar' === $key ) { $pillar = Digitalisimo_Integrations_Editorial::cluster_candidate_id( $value ); $current[ $key ] = $pillar ? get_post_field( 'post_name', $pillar ) : ''; continue; }
			if ( in_array( $key, self::secret_keys(), true ) && '' === trim( (string) $value ) ) continue; // La ruta de acceso necesita su propia validación: un valor reservado dejaría la red sin escritorio.
			if ( Digitalisimo_Integrations_Hide_Login::KEY === $key ) { $current[ $key ] = Digitalisimo_Integrations_Hide_Login::sanitize_slug( $value ); continue; }
			// Las URLs de archivo se guardan como URL, no como texto plano.
			if ( in_array( $key, self::media_keys(), true ) ) { $current[ $key ] = esc_url_raw( trim( (string) $value ) ); continue; }
			if ( Digitalisimo_Integrations_Social_Profiles::KEY === $key ) { $current[ $key ] = Digitalisimo_Integrations_Social_Profiles::sanitize( $value, $current[ $key ] ?? array() ); continue; }
			if ( Digitalisimo_Integrations_Social_Profiles::LEGACY === $key ) { $current[ $key ] = Digitalisimo_Integrations_Social_Profiles::sanitize_extras( $value ); continue; }
			if ( Digitalisimo_Integrations_Local_Business::SCHEDULE === $key ) { $current[ $key ] = Digitalisimo_Integrations_Local_Business::sanitize_schedule( $value ); continue; }
			if ( Digitalisimo_Integrations_Local_Business::PHONE_CC === $key ) { $current[ $key ] = Digitalisimo_Integrations_Local_Business::sanitize_code( $value ); continue; }
			if ( Digitalisimo_Integrations_Local_Business::PHONE === $key ) { $current[ $key ] = Digitalisimo_Integrations_Local_Business::sanitize_phone( $value ); continue; }
			$current[ $key ] = sanitize_textarea_field( $value ); } update_site_option( Digitalisimo_Integrations_Settings::OPTION, $current ); wp_safe_redirect( network_admin_url( 'admin.php?page=digitalisimo-network-seo&updated=1&tab=' . sanitize_key( $_POST['digitalisimo_active_tab'] ?? 'general' ) ) ); exit; }
	public static function page() {
		if ( ! current_user_can( 'manage_options' ) ) return; $slug = sanitize_key( $_GET['page'] ?? 'digitalisimo-seo' ); $map = array( 'digitalisimo-seo' => 'dashboard', 'digitalisimo-seo-general' => 'general', 'digitalisimo-seo-titles' => 'titles', 'digitalisimo-seo-appearance' => 'appearance', 'digitalisimo-seo-schema' => 'schema', 'digitalisimo-seo-local' => 'local', 'digitalisimo-seo-social' => 'social', 'digitalisimo-seo-sitemap' => 'sitemap', 'digitalisimo-seo-indexing' => 'indexing', 'digitalisimo-seo-breadcrumbs' => 'breadcrumbs', 'digitalisimo-seo-tools' => 'tools', 'digitalisimo-seo-diagnostic' => 'diagnostic' ); $section = $map[ $slug ] ?? 'dashboard';
		echo '<div class="wrap digitalisimo-admin-shell"><h1>SEO · Digitalisimo</h1><p>Configura las señales SEO del sitio desde un solo lugar.</p>'; self::navigation_tabs( $section );
		if ( 'dashboard' === $section ) { self::dashboard(); echo '</div>'; return; } if ( 'diagnostic' === $section ) { self::diagnostic(); echo '</div>'; return; } if ( 'tools' === $section ) { self::tools(); echo '</div>'; return; }
		echo '<form method="post" action="options.php">'; settings_fields( 'digitalisimo_integrations' ); echo '<table class="form-table" role="presentation">'; self::settings_fields( $section ); echo '</table>'; submit_button( 'Guardar cambios SEO' ); echo '</form><script>document.querySelectorAll(".digitalisimo-network-inherit").forEach(function(c){var f=document.getElementById(c.dataset.field);function s(){if(f)f.disabled=c.checked;}c.addEventListener("change",s);s();});</script></div>';
	}
	private static function f( $key, $label, $type = 'text', $help = '' ) { $value = self::o( $key ); $name = Digitalisimo_Integrations_Settings::OPTION . '[' . $key . ']'; $inherit = is_multisite() && Digitalisimo_Integrations_SEO_Resolver::inherits_network( $key ); $disabled = $inherit ? ' disabled' : ''; echo '<tr><th scope="row"><label for="' . esc_attr( $key ) . '">' . esc_html( $label ) . '</label></th><td>'; if ( 'checkbox' === $type ) echo '<input type="hidden" name="' . esc_attr( $name ) . '" value="0"><label><input class="digitalisimo-inheritable" type="checkbox" id="' . esc_attr( $key ) . '" name="' . esc_attr( $name ) . '" value="1" ' . checked( $value, 1, false ) . $disabled . '> Activar</label>'; elseif ( 'textarea' === $type ) echo '<textarea class="large-text digitalisimo-inheritable" rows="4" id="' . esc_attr( $key ) . '" name="' . esc_attr( $name ) . '"' . $disabled . '>' . esc_textarea( $value ) . '</textarea>'; elseif ( 'media' === $type ) Digitalisimo_Media_Field::render( $key, $name, $value, (bool) $inherit, 'digitalisimo-inheritable' ); elseif ( 'select' === $type ) { $choices = func_get_arg( 4 ); echo '<select class="digitalisimo-inheritable" id="' . esc_attr( $key ) . '" name="' . esc_attr( $name ) . '"' . $disabled . '>'; foreach ( (array) $choices as $v => $l ) echo '<option value="' . esc_attr( $v ) . '" ' . selected( $value, $v, false ) . '>' . esc_html( $l ) . '</option>'; echo '</select>'; } else echo '<input class="regular-text digitalisimo-inheritable" type="' . esc_attr( $type ) . '" id="' . esc_attr( $key ) . '" name="' . esc_attr( $name ) . '" value="' . esc_attr( $value ) . '"' . $disabled . '>'; if ( $help ) echo '<p class="description">' . esc_html( $help ) . '</p>'; if ( is_multisite() ) { $origin = Digitalisimo_Integrations_SEO_Resolver::option_with_origin( $key ); echo '<p><input type="hidden" name="' . esc_attr( Digitalisimo_Integrations_Settings::OPTION ) . '[network_inherit][' . esc_attr( $key ) . ']" value="0"><label><input class="digitalisimo-network-inherit" data-field="' . esc_attr( $key ) . '" type="checkbox" name="' . esc_attr( Digitalisimo_Integrations_Settings::OPTION ) . '[network_inherit][' . esc_attr( $key ) . ']" value="1" ' . checked( $inherit, true, false ) . '> Heredar de la red</label><br><span class="description">Valor efectivo: <strong>' . esc_html( is_scalar( $origin['value'] ) ? (string) $origin['value'] : '' ) . '</strong> · Origen: ' . esc_html( $origin['label'] ) . '</span></p>'; } echo '</td></tr>'; }
	private static function settings_fields( $s ) {
