	public static function save_post( $id ) {
		if ( wp_is_post_revision( $id ) || ! isset( $_POST['digitalisimo_native_seo_nonce'] ) || ! wp_verify_nonce( sanitize_text_field( wp_unslash( $_POST['digitalisimo_native_seo_nonce'] ) ), 'digitalisimo_native_seo' ) || ! current_user_can( 'edit_post', $id ) ) return;
		foreach ( array( 'title', 'description', 'social_title', 'social_description', 'local_note' ) as $key ) if ( isset( $_POST[ 'digitalisimo_native_' . $key ] ) ) update_post_meta( $id, self::P . $key, sanitize_textarea_field( wp_unslash( $_POST[ 'digitalisimo_native_' . $key ] ) ) );
		foreach ( array( 'canonical', 'social_image' ) as $key ) if ( isset( $_POST[ 'digitalisimo_native_' . $key ] ) ) update_post_meta( $id, self::P . $key, esc_url_raw( wp_unslash( $_POST[ 'digitalisimo_native_' . $key ] ) ) );
		foreach ( array( 'noindex', 'nofollow' ) as $key ) update_post_meta( $id, self::P . $key, isset( $_POST[ 'digitalisimo_native_' . $key ] ) ? '1' : '' );
		update_post_meta( $id, self::P . 'schema_type', sanitize_key( wp_unslash( $_POST['digitalisimo_native_schema_type'] ?? '' ) ) );
		$json = trim( wp_unslash( $_POST['digitalisimo_native_schema_custom'] ?? '' ) );
		update_post_meta( $id, self::P . 'schema_custom', json_decode( $json, true ) ? wp_json_encode( json_decode( $json, true ), JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE ) : '' );
		$slug = sanitize_title( wp_unslash( $_POST['digitalisimo_native_slug'] ?? '' ) );
		$post = get_post( $id );
		if ( $slug && $post && $slug !== $post->post_name ) {
			remove_action( 'save_post', array( __CLASS__, 'save_post' ), 15 );
			wp_update_post( array( 'ID' => $id, 'post_name' => $slug ) );
			add_action( 'save_post', array( __CLASS__, 'save_post' ), 15 );
		}
	}
	public static function taxonomies() { foreach ( self::list_value( 'seo_taxonomies' ) as $tax ) if ( taxonomy_exists( $tax ) ) { add_action( $tax . '_add_form_fields', array( __CLASS__, 'term_fields' ) ); add_action( $tax . '_edit_form_fields', array( __CLASS__, 'term_fields' ) ); } }
	public static function term_fields( $term ) { $id = is_object( $term ) ? $term->term_id : 0; $get = function( $k ) use ( $id ) { return $id ? get_term_meta( $id, self::P . $k, true ) : ''; }; wp_nonce_field( 'digitalisimo_term_seo', 'digitalisimo_term_seo_nonce' ); echo '<div class="form-field"><label>Título SEO</label><input name="digitalisimo_term_title" value="' . esc_attr( $get( 'title' ) ) . '"></div><div class="form-field"><label>Meta descripción</label><textarea name="digitalisimo_term_description">' . esc_textarea( $get( 'description' ) ) . '</textarea></div><div class="form-field"><label><input type="checkbox" name="digitalisimo_term_noindex" value="1" ' . checked( '1', $get( 'noindex' ), false ) . '> noindex</label></div>'; }
	public static function save_term( $id ) { if ( ! isset( $_POST['digitalisimo_term_seo_nonce'] ) || ! wp_verify_nonce( sanitize_text_field( wp_unslash( $_POST['digitalisimo_term_seo_nonce'] ) ), 'digitalisimo_term_seo' ) ) return; update_term_meta( $id, self::P . 'title', sanitize_text_field( wp_unslash( $_POST['digitalisimo_term_title'] ?? '' ) ) ); update_term_meta( $id, self::P . 'description', sanitize_textarea_field( wp_unslash( $_POST['digitalisimo_term_description'] ?? '' ) ) ); update_term_meta( $id, self::P . 'noindex', isset( $_POST['digitalisimo_term_noindex'] ) ? '1' : '' ); }
	private static function replace( $template, $context = array() ) { $site = self::o( 'seo_site_name' ) ?: get_bloginfo( 'name' ); $repl = array( '%sitename%' => $site, '%sep%' => self::o( 'seo_separator' ) ?: '|', '%title%' => $context['title'] ?? '', '%term%' => $context['term'] ?? '', '%excerpt%' => $context['excerpt'] ?? '', '%description%' => $context['description'] ?? '', '%page%' => is_paged() ? 'Página ' . get_query_var( 'paged' ) : '' ); return trim( preg_replace( '/\s+/', ' ', strtr( (string) $template, $repl ) ) ); }
	private static function current() { if ( is_singular() ) { $id = get_queried_object_id(); $p = get_post( $id ); $type = $p ? $p->post_type : 'post'; $fallback = 'page' === $type ? 'page' : 'post'; $excerpt = $p ? wp_trim_words( wp_strip_all_tags( $p->post_content ), 30, '' ) : ''; $title = get_post_meta( $id, self::P . 'title', true ) ?: self::replace( self::o( 'seo_title_' . $fallback ), array( 'title' => get_the_title( $id ), 'excerpt' => $excerpt ) ); $description = get_post_meta( $id, self::P . 'description', true ) ?: self::replace( self::o( 'seo_description_' . $fallback ), array( 'title' => get_the_title( $id ), 'excerpt' => $excerpt ) ); $title = $title ?: get_the_title( $id ); $description = $description ?: ( $excerpt ?: get_bloginfo( 'description' ) ); return array( 'id' => $id, 'title' => $title, 'description' => $description, 'canonical' => get_post_meta( $id, self::P . 'canonical', true ) ?: get_permalink( $id ) ); } if ( is_tax() || is_category() || is_tag() ) { $t = get_queried_object(); $desc = term_description( $t ); return array( 'term' => $t, 'title' => get_term_meta( $t->term_id, self::P . 'title', true ) ?: self::replace( self::o( 'seo_title_taxonomy' ), array( 'term' => $t->name, 'description' => wp_strip_all_tags( $desc ) ) ), 'description' => get_term_meta( $t->term_id, self::P . 'description', true ) ?: self::replace( self::o( 'seo_description_taxonomy' ), array( 'term' => $t->name, 'description' => wp_strip_all_tags( $desc ) ) ), 'canonical' => get_term_link( $t ) ); } $object = get_queried_object(); $base = is_search() ? sprintf( 'Resultados para: %s', get_search_query() ) : ( is_author() && $object ? $object->display_name : ( is_post_type_archive() && $object ? $object->labels->name : get_bloginfo( 'name' ) ) ); return array( 'title' => self::replace( self::o( 'seo_title_archive' ), array( 'title' => $base ) ), 'description' => self::replace( self::o( 'seo_description_archive' ), array( 'title' => $base ) ), 'canonical' => self::canonical_url() ); }
	public static function title( $title ) { $c = self::current(); return $c['title'] ?: $title; }
	private static function canonical_url() { global $wp; return home_url( add_query_arg( array(), $wp->request ?? '' ) ); }
	private static function should_noindex() { if ( is_search() && self::o( 'noindex_search' ) ) return true; if ( is_author() && self::o( 'noindex_authors' ) ) return true; if ( is_date() && self::o( 'noindex_date_archives' ) ) return true; if ( is_attachment() && self::o( 'noindex_attachments' ) ) return true; if ( is_singular( 'elementor_library' ) && self::o( 'noindex_elementor' ) ) return true; if ( is_tag() && self::o( 'noindex_empty_tags' ) && ! (int) get_queried_object()->count ) return true; if ( self::o( 'noindex_woo_pages' ) && ( ( function_exists( 'is_cart' ) && is_cart() ) || ( function_exists( 'is_checkout' ) && is_checkout() ) || ( function_exists( 'is_order_received_page' ) && is_order_received_page() ) ) ) return true; if ( is_singular() ) { $id = get_queried_object_id(); $legacy_robots = (array) get_post_meta( $id, self::P . 'robots', true ); if ( '1' === get_post_meta( $id, self::P . 'noindex', true ) || in_array( 'noindex', $legacy_robots, true ) ) return true; $slugs = preg_split( '/\r\n|\r|\n/', (string) self::o( 'noindex_page_slugs' ) ); $ids = array_map( 'absint', explode( ',', (string) self::o( 'noindex_page_ids' ) ) ); if ( in_array( get_post_field( 'post_name', $id ), array_map( 'sanitize_title', $slugs ), true ) || in_array( $id, $ids, true ) ) return true; } if ( ( is_tax() || is_category() || is_tag() ) && '1' === get_term_meta( get_queried_object_id(), self::P . 'noindex', true ) ) return true; return false; }
	public static function robots( $robots ) { if ( self::should_noindex() ) $robots['noindex'] = true; if ( is_singular() && '1' === get_post_meta( get_queried_object_id(), self::P . 'nofollow', true ) ) $robots['nofollow'] = true; return $robots; }
	public static function head() { if ( is_admin() || is_feed() ) return; $c = self::current(); if ( ! empty( $c['description'] ) ) echo '<meta name="description" content="' . esc_attr( wp_strip_all_tags( $c['description'] ) ) . '">' . "\n"; if ( ! empty( $c['id'] ) && ( $keywords = get_post_meta( $c['id'], self::P . 'keywords', true ) ) ) echo '<meta name="keywords" content="' . esc_attr( wp_strip_all_tags( is_array( $keywords ) ? implode( ', ', $keywords ) : $keywords ) ) . '">' . "\n"; if ( ! empty( $c['canonical'] ) && ! is_wp_error( $c['canonical'] ) ) echo '<link rel="canonical" href="' . esc_url( $c['canonical'] ) . '">' . "\n"; if ( self::o( 'seo_open_graph' ) ) self::social( $c ); if ( self::o( 'seo_schema_enabled' ) ) self::schema( $c ); }
