	public static function breadcrumbs( $schema = false ) { $items = array( array( 'name' => 'Inicio', 'url' => home_url( '/' ) ) ); if ( is_singular() ) { $id = get_queried_object_id(); if ( $parent = absint( get_post_meta( $id, '_related_pillar', true ) ) ) $items[] = array( 'name' => get_the_title( $parent ), 'url' => get_permalink( $parent ) ); $items[] = array( 'name' => get_the_title( $id ), 'url' => get_permalink( $id ) ); } if ( $schema ) { $out = array(); foreach ( $items as $i => $item ) $out[] = array( '@type' => 'ListItem', 'position' => $i + 1, 'name' => $item['name'], 'item' => $item['url'] ); return $out; } return $items; }
